pm.test("Status code is 200", function () {
    pm.response.to.have.status(200)
})

pm.test("Response has correct callback response type", function () {
    pm.expect(pm.response.json()).to.have.property('type', 'cti.a.p.acgw.response.v1.0~a.p.enablement.read.ok.v1.0')
})

pm.test("Response matches against the callback schema", function () {
    const responseSchema = {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "$ref": "#/definitions/EnablementRead.OK",
        "definitions": {
            "EnablementRead.OK": {
                "type": "object",
                "properties": {
                    "payload": {
                        "type": "object",
                        "additionalProperties": false,
                        "properties": {
                            "vendor_tenant_id": {
                                "description": "Vendor's tenant id associated with authorization info",
                                "type": "string"
                            },
                            "acronis_tenant_id": {
                                "type": "string",
                                "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$",
                                "description": "Acronis tenant id used for application enablement"
                            }
                        },
                        "required": [
                            "vendor_tenant_id"
                        ]
                    }
                },
                "required": [
                    "payload"
                ]
            }
        }
    }

    pm.expect(pm.response.json()).to.have.jsonSchema(responseSchema)
})
